public void initializeEntityDataSource(DataEntityRuntimeContext entityCtx, DataEntityDataSourceRuntimeContext dataSourceCtx)
{
    RetailDiscountEntity discount = RetailDiscountEntity::find(this.OfferId);
    if (!discount)
    {
        throw error(strFmt("@Retail:CannotFindOffer", this.OfferId));
    }

    RetailPeriodicDiscountLine discountLine;
    RetailDiscountLineOffer offerLine;
    RetailDiscountLineMixAndMatch mixAndMatchLine;
    RetailDiscountLineMultibuy multibuyLine;
    RetailDiscountLineThresholdApplying thresholdApplyingLine;
    GUPFreeItemDiscountLine freeItemLine;

    if (dataSourceCtx.name() == tablestr(RetailPeriodicDiscountLine))
    {
        if (dataSourceCtx.getDatabaseOperation() == DataEntityDatabaseOperation::Update)
        {
            discountLine = dataSourceCtx.getBuffer();
            switch (discount.PeriodicDiscountType)
            {
                case RetailDiscountOfferTypeBase::DiscountOffer:
                case RetailDiscountOfferTypeBase::Promotion:
                case RetailDiscountOfferTypeBase::DiscountOfferLineQuantityLimit:
                    offerLine = discountLine as RetailDiscountLineOffer;
                    dataSourceCtx.setBuffer(offerLine);
                    break;
                case RetailDiscountOfferTypeBase::Multibuy:
                    multibuyLine = discountLine as RetailDiscountLineMultibuy;
                    dataSourceCtx.setBuffer(multibuyLine);
                    break;
                case RetailDiscountOfferTypeBase::MixAndMatch:
                    mixAndMatchLine = discountLine as RetailDiscountLineMixAndMatch;
                    dataSourceCtx.setBuffer(mixAndMatchLine);
                    break;
                case RetailDiscountOfferTypeBase::FreeItem:
                    freeItemLine = discountLine as GUPFreeItemDiscountLine;
                    dataSourceCtx.setBuffer(freeItemLine);
                    break;
                case RetailDiscountOfferTypeBase::Threshold:
                    if (discountLine.IsDiscountApplyingLine == NoYes::Yes)
                    {
                        thresholdApplyingLine = discountLine as RetailDiscountLineThresholdApplying;
                        dataSourceCtx.setBuffer(thresholdApplyingLine);
                    }
                    break;
            }
        }
        else if (dataSourceCtx.getDatabaseOperation() == DataEntityDatabaseOperation::Insert)
        {
            switch (discount.PeriodicDiscountType)
            {
                case RetailDiscountOfferTypeBase::DiscountOffer:
                case RetailDiscountOfferTypeBase::Promotion:
                case RetailDiscountOfferTypeBase::DiscountOfferLineQuantityLimit:
                    dataSourceCtx.setBuffer(new DictTable(tablenum(RetailDiscountLineOffer)).makeRecord());
                    break;
                case RetailDiscountOfferTypeBase::Multibuy:
                    dataSourceCtx.setBuffer(new DictTable(tablenum(RetailDiscountLineMultibuy)).makeRecord());
                    break;
                case RetailDiscountOfferTypeBase::MixAndMatch:
                    dataSourceCtx.setBuffer(new DictTable(tablenum(RetailDiscountLineMixAndMatch)).makeRecord());
                    break;
                case RetailDiscountOfferTypeBase::FreeItem:
                    dataSourceCtx.setBuffer(new DictTable(tablenum(GUPFreeItemDiscountLine)).makeRecord());
                    break;
                case RetailDiscountOfferTypeBase::Threshold:
                    if (this.IsDiscountApplyingLine == NoYes::Yes)
                    {
                        dataSourceCtx.setBuffer(new DictTable(tablenum(RetailDiscountLineThresholdApplying)).makeRecord());
                    }
                    break;
            }
        }
    }
    else if (dataSourceCtx.name() == dataEntityDataSourceStr(GUPMarginComponentPriceAdjustmentLineEntity, InventDim))
    {
        dataSourceCtx.setDataSaved(true);
        dataSourceCtx.setDatabaseOperation(DataEntityDatabaseOperation::None);
    }

    super(entityCtx, dataSourceCtx);
}

public void mapEntityToDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    // Discount line group isn't ready for validation yet, as it may not exist yet. We'll validate it and may populate it later in insert and update.
    this.skipDataSourceValidateField(fieldNum(RetailDiscountLineEntity, MixAndMatchLineGroup), true);

    switch(_dataSourceCtx.name())
    {
        case dataEntityDataSourceStr(RetailDiscountLineEntity, RetailDiscountThresholdTiers):
            if (this.IsDiscountApplyingLine == NoYes::No)
            {
                _dataSourceCtx.setDatabaseOperation(DataEntityDatabaseOperation::None);
            }
            else
            {
                RetailDiscountThresholdTiers tier = _dataSourceCtx.getBuffer();
                tier.RecId = this.ThresholdTierRecId;
                tier.OfferId = this.OfferId;
                tier.AmountThreshold = this.ThresholdTierAmount;
                _dataSourceCtx.setBuffer(tier);
            }
            break;

        case dataEntityDataSourceStr(RetailDiscountLineEntity, RetailPeriodicDiscountLine):
            if (this.IsDiscountApplyingLine == NoYes::Yes)
            {
                RetailDiscountEntity discount = RetailDiscountEntity::find(this.OfferId);
                if (discount && discount.PeriodicDiscountType == RetailDiscountOfferTypeBase::Threshold)
                {
                    RetailPeriodicDiscountLine discountLine = _dataSourceCtx.getBuffer();

                    RetailDiscountThresholdTiers tier;
                    select firstonly RecId from tier where tier.OfferId == this.OfferId && tier.AmountThreshold == this.ThresholdTierAmount;

                    if (tier.RecId)
                    {
                        RetailDiscountLineThresholdApplying thresholdApplyingLine = discountLine;
                        thresholdApplyingLine.Tier = tier.RecId;
                        thresholdApplyingLine.QuantityLimit = this.ThresholdLineQuantityLimit;
                        thresholdApplyingLine.ThresholdLineDiscountMethod = this.ThresholdApplyingLineDiscountMethod;

                        _dataSourceCtx.setBuffer(thresholdApplyingLine);

                        this.ThresholdTierRecId = tier.RecId;
                    }
                }
            }

            break;

        default:
            break;
    }

    super(_entityCtx, _dataSourceCtx);
}

public boolean insertEntityDataSource(DataEntityRuntimeContext entityCtx, DataEntityDataSourceRuntimeContext dataSourceCtx)
{
    boolean ret;

    ret = this.validateDiscountLineAndFixGroupMemberLine(entityCtx, dataSourceCtx);

    if (dataSourceCtx.name() == tablestr(RetailPeriodicDiscountLine))
    {
        dataSourceCtx.skipDataMethods(true);
        RetailPeriodicDiscountLine line = dataSourceCtx.getBuffer();
        RetailPeriodicDiscount discount = RetailPeriodicDiscount::findByOfferId(line.OfferId);
        if (!discount)
        {
            throw error(strfmt("@GlobalUnifiedPricing:GUPDataEntityInvalidRelationError", tablePName(RetailPeriodicDiscount), line.OfferId));
        }
        if (discount.Status == RetailDisabledEnabled::Enabled)
        {
            throw error(strFmt("@RetailDiscount:NotAllowEditEnabledDiscount"));
        }
        this.updatePriceComponentCodeAndGroupCombination(discount, line, this.PriceAttributeGroupType, this.PriceAttributeGroupName);
        this.createOrUpdateRule(line, this.PriceAttributeGroupType, this.PriceAttributeGroupName);
        this.createOrUpdateInventDim(line);
        this.updateRetailGroupMemberLine(line);
    }

    ret = ret && super(entityCtx, dataSourceCtx);

    return ret;
}

public boolean updateEntityDataSource(DataEntityRuntimeContext entityCtx, DataEntityDataSourceRuntimeContext dataSourceCtx)
{
    boolean ret;

    ret = this.validateDiscountLineAndFixGroupMemberLine(entityCtx,dataSourceCtx);

    if (dataSourceCtx.name() == tablestr(RetailPeriodicDiscountLine))
    {
        RetailPeriodicDiscountLine line = dataSourceCtx.getBuffer();
        RetailPeriodicDiscount discount = RetailPeriodicDiscount::findByOfferId(line.OfferId);
        if (!discount)
        {
            throw error(strfmt("@GlobalUnifiedPricing:GUPDataEntityInvalidRelationError", tablePName(RetailPeriodicDiscount), line.OfferId));
        }
        if (discount.Status == RetailDisabledEnabled::Enabled)
        {
            throw error(strFmt("@RetailDiscount:NotAllowEditEnabledDiscount"));
        }
        this.updatePriceComponentCodeAndGroupCombination(discount, line, this.PriceAttributeGroupType, this.PriceAttributeGroupName);
        this.createOrUpdateRule(line, this.PriceAttributeGroupType, this.PriceAttributeGroupName);
        this.createOrUpdateInventDim(line);
        RetailGroupMemberLine groupMemberLine = RetailGroupMemberLine::find(line.RetailGroupMemberLine);
        if (!groupMemberLine)
        {
            this.updateRetailGroupMemberLine(line);
        }
    }

    ret = ret && super(entityCtx, dataSourceCtx);

    return ret;
}

public void postLoad()
{
    super();
    if (this.PriceAttributeGroupType == GUPGroupAll::Group && this.LinePricingRule)
    {
        GUPPricingRule rule;
        select firstonly crosscompany rule where rule.RecId == this.LinePricingRule;

        if (rule.PriceAttributeGroupName)
        {
            int num = 1;
            str baseFieldName = "Line";
            GUPPricingRuleCondition ruleCondition;
            GUPPricingAttributeLink attributeLink;
            while select crosscompany ruleCondition
            where ruleCondition.RuleId == this.LinePricingRule
            join attributeLink
            order by attributeLink.Priority asc
            where ruleCondition.ConditionAttribute == attributeLink.RecId
            {
                this.setFieldValue(baseFieldName + int2Str(num), ruleCondition.ConditionValue);
                num++;
            }
        }
    }
}

public boolean validateField(FieldId _fieldIdToCheck)
{
    boolean ret;
    ret = super(_fieldIdToCheck);

    if (_fieldIdToCheck == fieldNum(GUPRetailDiscountLineEntity, UnitOfMeasureSymbol))
    {
        if (this.UnitOfMeasureSymbol)
        {
            ret = ret && this.checkUnitSymbol(this.UnitOfMeasureSymbol);
        }
    }
    return ret;
}

private boolean validateDiscountLineAndFixGroupMemberLine(DataEntityRuntimeContext entityCtx, DataEntityDataSourceRuntimeContext dataSourceCtx)
{
    if (dataSourceCtx.name() == tablestr(RetailPeriodicDiscountLine))
    {
        RetailDiscountEntity discount = RetailDiscountEntity::find(this.OfferId);

        if (!discount)
        {
            throw error(strFmt("@Retail:CannotFindOffer", this.OfferId));
        }

        this.validateDiscountLine(discount);
        this.resetProcessStatus(this.OfferId);
    }

    return true;
}

private void validateDiscountLine(RetailDiscountEntity discount)
{
    if (discount.PeriodicDiscountType == RetailDiscountOfferTypeBase::MixAndMatch)
    {
        if (!this.MixAndMatchLineGroup)
        {
            throw error(strFmt("@Retail:MixAndMatchLineGroupRequired", this.LineNum));
        }
        else
        {
            RetailMixAndMatchLineGroupSetup lineGroupSetup = RetailMixAndMatchLineGroupSetup::find(this.MixAndMatchLineGroup);
            if (!lineGroupSetup)
            {
                throw error(strFmt("@Retail:BadMixAndMatchLineGroup", this.MixAndMatchLineGroup));
            }
        }

        if (this.MixAndMatchNumberOfItemsNeeded < 1)
        {
            throw error(strFmt("@Retail:BadMixAndMatchNumberOfItemsNeeded", this.MixAndMatchNumberOfItemsNeeded));
        }

        RetailMixAndMatchLineGroups mixMatchLineGroup;
        select forupdate mixMatchLineGroup where mixMatchLineGroup.mixAndMatchId == this.OfferId && mixMatchLineGroup.mixAndMatchLineGroup == this.MixAndMatchLineGroup;
        if (mixMatchLineGroup)
        {
            if (mixMatchLineGroup.numberOfItemsNeeded != this.MixAndMatchNumberOfItemsNeeded)
            {
                mixMatchLineGroup.numberOfItemsNeeded = this.MixAndMatchNumberOfItemsNeeded;
                mixMatchLineGroup.update();
            }
        }
        else
        {
            mixMatchLineGroup.mixAndMatchId = this.OfferId;
            mixMatchLineGroup.mixAndMatchLineGroup = this.MixAndMatchLineGroup;
            mixMatchLineGroup.numberOfItemsNeeded = this.MixAndMatchNumberOfItemsNeeded;
            mixMatchLineGroup.insert();
        }

        if (discount.MixAndMatchDiscountType == RetailMixAndMatchDiscountType::LineSpec)
        {
            switch (this.MixAndMatchDiscountType)
            {
                case RetailDealPriceDiscountPctBase::DealPrice:
                    if (!RetailMonetaryUtilities::isValidDiscountDealPriceAllowZero(this.DiscountPercentOrValue))
                    {
                        throw error(strFmt("@Retail:IncorrectMixAndMatchLineDealPrice", this.DiscountPercentOrValue));
                    }
                    break;
                case RetailDealPriceDiscountPctBase::DiscountPct:
                    if (!RetailMonetaryUtilities::isValidDiscountPercentageAllowZero(this.DiscountPercentOrValue))
                    {
                        throw error(strFmt("@Retail:IncorrectMixAndMatchLinePercentOff", this.DiscountPercentOrValue));
                    }
                    break;
                case RetailDealPriceDiscountPctBase::DiscountAmount:
                    if (!RetailMonetaryUtilities::isValidDiscountAmountAllowZero(this.DiscountPercentOrValue))
                    {
                        throw error(strFmt("@RetailDiscount:IncorrectMixAndMatchLineAmountOff", this.DiscountPercentOrValue));
                    }
                    break;
                default:
                    throw error(strFmt("@Retail:IncorrectMixAndMatchLineDiscountType", this.MixAndMatchDiscountType));
            }
        }
    }
}

private void updatePriceComponentCodeAndGroupCombination(RetailPeriodicDiscount _discount, RetailPeriodicDiscountLine _line, GUPGroupAll _type, Name _groupName)
{
    RetailPeriodicDiscount discount = RetailPeriodicDiscount::findByOfferId(_line.OfferId);
    GUPPriceComponent allowedPriceComponent;

    switch (discount.PeriodicDiscountType)
    {
        case RetailDiscountOfferTypeBase::Promotion:
            allowedPriceComponent = GUPPriceComponent::PriceMarginComponentAdjustment;
            break;
        case RetailDiscountOfferTypeBase::DiscountOffer:
        case RetailDiscountOfferTypeBase::DiscountOfferLineQuantityLimit:
        case RetailDiscountOfferTypeBase::Multibuy:
        case RetailDiscountOfferTypeBase::MixAndMatch:
        case RetailDiscountOfferTypeBase::LeastExpensiveFavorRetailer:
        case RetailDiscountOfferTypeBase::Threshold:
        case RetailDiscountOfferTypeBase::FreeItem:
            allowedPriceComponent = GUPPriceComponent::RetailDiscounts;
            break;
    }

    GUPPriceComponentCode componentCode;
    select firstonly componentCode
        where componentCode.PriceComponent == allowedPriceComponent && componentCode.Name == _discount.PriceComponentCodeName;
    if (!componentCode)
    {
        throw error(strfmt("@GlobalUnifiedPricing:GUPDataEntityInvalidRelationError", tablePName(GUPPriceComponentCode), _discount.PriceComponentCodeName));
    }

    if (_type == GUPGroupAll::All)
    {
        if (!componentCode.LinePriceAttributeGroupAllEnabled)
        {
            throw error(strfmt("@GlobalUnifiedPricing:GUPPriceComponentCode_TypeAllNotEnabledError", _discount.PriceComponentCodeName));
        }
    }

    GUPPricingRule headerRule = GUPPricingRule::find(_discount.HeaderPricingRule);
    GUPPriceComponentCodePriceAttributeGroupCombination groupCombination;
    select firstonly groupCombination
        where groupCombination.PriceComponentCodeName == _discount.PriceComponentCodeName
        && groupCombination.HeaderGroupAll == _discount.HeaderPricingGroupCode
        && groupCombination.LineGroupAll == _type
        && groupCombination.HeaderPriceAttributeGroupName == headerRule.PriceAttributeGroupName
        && groupCombination.LinePriceAttributeGroupName == _groupName;
    if (!groupCombination)
    {
        throw error(strfmt("@GlobalUnifiedPricing:GUPDataEntityInvalidRelationError", "Attribute group combination", headerRule.PriceAttributeGroupName + "-" + _groupName + " with type = " + enum2Str(_type)));
    }
    _line.PriceAttributeGroupCombinationRecId = groupCombination.RecId;
}

private GUPPricingAttributeGroup getAndValidateAttributeGroup(Name _name)
{
    GUPPricingAttributeGroup attributeGroup;
    select firstonly attributeGroup
        where attributeGroup.Name == _name
        && attributeGroup.SourceLevel == GUPPricingAttributeSourceLevel::Line
        && attributeGroup.GroupType == GUPPricingAttributeGroupType::General;

    if (!attributeGroup)
    {
        throw error(strfmt("@GlobalUnifiedPricing:GUPDataEntityInvalidRelationError", tablePName(GUPPricingAttributeGroup), _name));
    }

    return attributeGroup;
}

private boolean createOrUpdatePricingRuleCondition(RefRecId _ruleId, GUPRefRecId _conditionAttribute, AttributeValueText _value, str _fieldName)
{
    GUPPricingRuleCondition condition = GUPPricingRuleCondition::find(_ruleId, _conditionAttribute, true);
    if (condition)
    {
        condition.ConditionValue = _value;
        if (!condition.validateWrite())
        {
            throw error(strfmt("@GlobalUnifiedPricing:GUPDataEntityInvalidFieldValue", _value, _fieldName));
        }
        condition.update();
    }
    else
    {
        condition.RuleId = _ruleId;
        condition.ConditionAttribute = _conditionAttribute;
        condition.ConditionValue = _value;
        if (!condition.validateWrite())
        {
            throw error(strfmt("@GlobalUnifiedPricing:GUPDataEntityInvalidFieldValue", _value, _fieldName));
        }
        condition.insert();
    }
    return true;
}

private void createOrUpdateRule(RetailPeriodicDiscountLine _line, GUPGroupAll _type, GUPPricingAttributeGroupName _groupName)
{
    GUPPricingRule rule = GUPPricingRule::find(_line.LinePricingRule, true);
    switch (_type)
    {
        case GUPGroupAll::All :
            if (!rule)
            {
                rule = GUPPricingRule::newPricingRule("", GUPPricingRuleExclusionType::Product);
                _line.LinePricingRule = rule.RecId;
            }
            if (rule.PriceAttributeGroupName)
            {
                rule.PriceAttributeGroupName = "";
                rule.update();
            }
            break;
        case GUPGroupAll::Group :
            ttsbegin;
            GUPPricingAttributeGroup attributeGroup = this.getAndValidateAttributeGroup(_groupName);
            if (!rule)
            {
                rule = GUPPricingRule::newPricingRule(attributeGroup.Name, GUPPricingRuleExclusionType::Customer);
                _line.LinePricingRule = rule.RecId;
            }
            if (rule.PriceAttributeGroupName != attributeGroup.Name)
            {
                rule.PriceAttributeGroupName = attributeGroup.Name;
                rule.update();
            }
            int num = 1;
            str baseFieldName = "Line";
            GUPPricingAttributeLink attributeLink;
            while select attributeLink
                    order by attributeLink.Priority asc
                    where attributeLink.PriceAttributeGroupName == attributeGroup.Name
            {
                this.createOrUpdatePricingRuleCondition(rule.RecId, attributeLink.RecId, this.getFieldValue(baseFieldName + int2Str(num)), baseFieldName + int2Str(num));
                num ++;
            }
            ttscommit;
            break;
    }
}

private void createOrUpdateInventDim(RetailPeriodicDiscountLine _line)
{
    InventDim inventDim;
    inventDim.configId = this.Configuration;
    inventDim.InventSizeId = this.Size;
    inventDim.InventColorId = this.Color;
    inventDim.InventStyleId = this.Style;
    inventDim.InventSiteId = this.Site;
    inventDim.InventLocationId = this.Warehouse;
    inventDim.wMSLocationId = this.Location;
    inventDim.InventStatusId = this.InventoryStatus;
    inventDim.LicensePlateId = this.LicensePlate;
    inventDim.inventBatchId = this.BatchNumber;
    inventDim.inventSerialId = this.SerialNumber;
    inventDim.InventOwnerId_RU = this.Owner;
    inventDim = InventDim::findOrCreate(inventDim);
    _line.InventDimId = inventDim.inventDimId;
}

private boolean checkUnitSymbol(UnitOfMeasureSymbol _symbol)
{
    boolean ret = true;
    UnitOfMeasure unit = UnitOfMeasure::findBySymbol(_symbol);
    if (!unit)
    {
        ret = checkFailed(strFmt("@GlobalUnifiedPricing:UnitOfMeasure_IncorrectSymbol", _symbol));
    }
    return ret;
}

private void updateRetailGroupMemberLine(RetailPeriodicDiscountLine _line)
{
    RetailGroupMemberLine groupMemberLine;
    groupMemberLine.Category = 0;
    groupMemberLine.Product = 0;
    groupMemberLine.Variant = 0;
    groupMemberLine.CategoryHierarchy = 0;
    groupMemberLine.insert();
    _line.RetailGroupMemberLine = groupMemberLine.RecId;
}

private boolean checkHeaderStatus(RetailPeriodicDiscountLine _line)
{
    boolean ret = true;
    RetailPeriodicDiscount discount = RetailPeriodicDiscount::findByOfferId(_line.OfferId);
    if (discount.Status == RetailDisabledEnabled::Enabled)
    {
        ret = checkFailed(strFmt("@RetailDiscount:NotAllowEditEnabledDiscount"));
    }
    return ret;
}

private void resetProcessStatus(RetailDiscountOfferId _offerId)
{
    ttsbegin;
    RetailPeriodicDiscount discount = RetailPeriodicDiscount::findByOfferId(_offerId, true);
    discount.update();
    ttscommit;
}
